#!/usr/bin/env python3
# -*- coding: utf-8 -*-
#
# Author: Rensc
# Date: 2026-06-24
# Version: 0.2.7.8
# Function: Core functions for RiboParser P-site offset analysis.
# Input: Function parameters and intermediate RiboParser data objects.
# Output: Processed data objects or output files generated by module functions.

"""SSCBM + RSBM P-site offset detection utilities for RiboParser.

This module is used by ``rpf_Offset``. It first detects offset from read-end
enrichment around TIS/TTS using SSCBM, then refines P-site offsets with RSBM.

Main workflow
-------------
1. Import transcript annotation.
2. Import BAM/SAM alignments and collect mapped reads by transcript.
3. Build TIS/TTS read-end profiles for SSCBM.
4. Infer initial P-site offsets from SSCBM.
5. Build RSBM candidate offsets, seeded by SSCBM when available.
6. Count reading-frame-supported P-site candidates.
7. Output SSCBM and RSBM offset tables and heatmap figures.
"""

from __future__ import annotations

import os
import sys
from collections import OrderedDict
from itertools import islice

import numpy as np
import pandas as pd
import pysam


FRAME_COLUMNS = [
    "length",
    "frame0",
    "rpfs0",
    "frame1",
    "rpfs1",
    "frame2",
    "rpfs2",
    "p_site",
    "rpfs",
]

TIS_OFFSET_COLUMNS = [
    "length",
    "frame0",
    "rpfs0",
    "frame1",
    "rpfs1",
    "frame2",
    "rpfs2",
    "p_site",
    "rpfs",
    "periodicity",
]


class Mrna:
    """Container for transcript annotation and mapped reads."""

    def __init__(self, record: list[str]):
        self.chromosome = record[0]
        self.gene_id = record[1]
        self.transcript_id = record[2]
        self.start = record[3]
        self.end = record[4]
        self.utr5_length = int(record[5])
        self.cds_length = int(record[6])
        self.utr3_length = int(record[7])
        self.strand = record[8]
        self.rep_transcript = record[9]
        self.modified = record[10] if len(record) > 10 else "False"
        self.bam = []
        self.rpf = []
        self.seq = None


class Offset:
    """Detect P-site offset using SSCBM followed by RSBM."""

    def __init__(self, args):
        self.min_length = args.min
        self.max_length = args.max
        self.longest = args.longest
        self.nt_num = self.max_length - self.min_length + 1

        self.mrna_file = args.transcript
        self.mrna_dict = OrderedDict()

        # SSCBM attributes.
        self.align = args.align
        self.tis_offset = {
            "tis_5end": OrderedDict(),
            "tis_3end": OrderedDict(),
            "tts_5end": OrderedDict(),
            "tts_3end": OrderedDict(),
        }
        self.adj_tis_offset = OrderedDict()
        self.tis_5end = None
        self.tis_3end = None
        self.tts_5end = None
        self.tts_3end = None

        self.detail = args.detail

        # RSBM attributes.
        self.frame_offset = OrderedDict()
        self.merge_frame_offset = pd.DataFrame(columns=FRAME_COLUMNS)
        self.frame_offset_len = {}
        self.exp_offset = None
        self.shift_nt = args.shift

        self.length_dict = {}

        # BAM/SAM parsing attributes.
        self.silence = args.silence
        self.sample_file = args.bam
        self.sample_format = os.path.splitext(args.bam)[1]
        self.pysam_input = None

        self.peak_length = args.exp_peak
        self.peak_reads = 0
        self.output_prefix = args.output

    # ------------------------------------------------------------------
    # Input readers
    # ------------------------------------------------------------------

    def read_transcript(self) -> None:
        """Read transcript annotation for offset detection.

        Notes
        -----
        If ``self.longest`` is True, only representative transcripts are
        retained. The representative transcript flag is column 10 in
        ``*.norm.txt``: index 9, column name ``rep_transcript``.
        """
        with open(self.mrna_file, "r", encoding="utf-8") as trans_file_in:
            for line in islice(trans_file_in, 1, None):
                line = line.strip()

                if not line:
                    continue

                record = line.split("\t")

                if self.longest and record[9] != "True":
                    continue

                now_mrna = Mrna(record)
                self.mrna_dict[now_mrna.transcript_id] = now_mrna

    def _get_alignment_mode(self) -> str:
        """Return pysam open mode according to BAM/SAM suffix."""
        sample_format = self.sample_format.lower()

        if sample_format == ".bam":
            print(f"import file: {self.sample_file}.\n", flush=True)
            return "rb"

        if sample_format == ".sam":
            print(f"import file: {self.sample_file}.\n", flush=True)
            return "r"

        print("Unknown file format, please input the correct BAM or SAM file.", flush=True)
        sys.exit(1)

    def get_mrna_reads(self) -> None:
        """Import BAM/SAM reads and calculate read length distribution."""
        read_format = self._get_alignment_mode()
        self.pysam_input = pysam.AlignmentFile(self.sample_file, read_format)

        for read in self.pysam_input.fetch(until_eof=True):
            transcript_id = read.reference_name

            if transcript_id in self.mrna_dict:
                read_length = read.infer_read_length()

                if read_length is None:
                    continue

                if read.is_reverse:
                    try:
                        self.length_dict[read_length][1] += 1
                    except KeyError:
                        self.length_dict[read_length] = [0, 1]
                else:
                    try:
                        self.length_dict[read_length][0] += 1
                    except KeyError:
                        self.length_dict[read_length] = [1, 0]

                self.mrna_dict[transcript_id].bam.append(read)

            elif self.silence:
                pass
            else:
                print(f"{transcript_id}: not in reference file.", flush=True)

        if not self.length_dict:
            print("No reads were mapped to transcripts in the reference file.", flush=True)
            self.pysam_input.close()
            sys.exit(1)

        _empirical_peak_length, peak_counts = max(
            self.length_dict.items(),
            key=lambda item: sum(item[1]),
        )
        self.peak_reads = sum(peak_counts)

        self.pysam_input.close()

    # ------------------------------------------------------------------
    # SSCBM offset detection
    # ------------------------------------------------------------------

    def get_tis_offset(self) -> None:
        """Build read-end profiles around TIS and TTS for SSCBM."""
        for read_length in range(self.min_length, self.max_length + 1):
            self.tis_offset["tis_5end"][read_length] = OrderedDict(
                {-i: 0 for i in range(self.max_length, -1, -1)}
            )
            self.tis_offset["tis_3end"][read_length] = OrderedDict(
                {i: 0 for i in range(self.max_length + 1)}
            )
            self.tis_offset["tts_5end"][read_length] = OrderedDict(
                {-i: 0 for i in range(self.max_length, -1, -1)}
            )
            self.tis_offset["tts_3end"][read_length] = OrderedDict(
                {i: 0 for i in range(self.max_length + 1)}
            )

        for mrna_attr in self.mrna_dict.values():
            if len(mrna_attr.bam) == 0:
                continue

            # TTS is shifted by 6 nt: 3 nt for stop codon, 2 nt for P-site,
            # and 1 nt for Python index convention in the legacy algorithm.
            cds_start = mrna_attr.utr5_length
            cds_end = mrna_attr.utr5_length + mrna_attr.cds_length - 6

            for read in mrna_attr.bam:
                blocks = read.get_blocks()

                if not blocks:
                    continue

                map_start, map_end = blocks[0]
                read_length = read.infer_read_length()

                if read_length is None:
                    continue

                if not (self.min_length <= read_length <= self.max_length):
                    continue

                if map_start <= cds_start <= map_end:
                    offset_5end = map_start - cds_start
                    offset_3end = map_end - cds_start

                    try:
                        self.tis_offset["tis_5end"][read_length][offset_5end] += 1
                        self.tis_offset["tis_3end"][read_length][offset_3end] += 1
                    except KeyError:
                        pass

                elif map_start <= cds_end <= map_end:
                    offset_5end = map_start - cds_end
                    offset_3end = map_end - cds_end

                    try:
                        self.tis_offset["tts_5end"][read_length][offset_5end] += 1
                        self.tis_offset["tts_3end"][read_length][offset_3end] += 1
                    except KeyError:
                        pass

        self.tis_5end = pd.DataFrame(self.tis_offset["tis_5end"]).T
        self.tis_3end = pd.DataFrame(self.tis_offset["tis_3end"]).T
        self.tts_5end = pd.DataFrame(self.tis_offset["tts_5end"]).T
        self.tts_3end = pd.DataFrame(self.tis_offset["tts_3end"]).T

        if self.detail:
            self.tis_5end.to_csv(
                self.output_prefix + "_tis_5end.txt",
                sep="\t",
                header=True,
                index=True,
            )
            self.tis_3end.to_csv(
                self.output_prefix + "_tis_3end.txt",
                sep="\t",
                header=True,
                index=True,
            )
            self.tts_5end.to_csv(
                self.output_prefix + "_tts_5end.txt",
                sep="\t",
                header=True,
                index=True,
            )
            self.tts_3end.to_csv(
                self.output_prefix + "_tts_3end.txt",
                sep="\t",
                header=True,
                index=True,
            )

    @staticmethod
    def offset_scale(offset: pd.DataFrame) -> pd.DataFrame:
        """Scale each row of an offset table by z-score."""
        offset_norm = offset.sub(offset.mean(axis=1), axis=0)
        offset_norm_row = offset_norm.div(offset_norm.std(axis=1), axis=0)
        offset_norm_row.fillna(0, inplace=True)
        return offset_norm_row

    def shift_codon(
        self,
        now_psite: int,
        length: int,
        left_offset: int,
        right_offset: int,
    ) -> int | float:
        """Shift P-site by codon steps into the expected P-site range."""
        if now_psite in range(left_offset, right_offset):
            return now_psite

        if self.adj_tis_offset:
            previous_psite = self.adj_tis_offset.get(length - 1, [None])[-1]

            if previous_psite:
                if previous_psite + 3 < now_psite:
                    return self.shift_codon(
                        now_psite - 3,
                        length,
                        left_offset,
                        right_offset,
                    )

                if now_psite < previous_psite - 3:
                    return self.shift_codon(
                        now_psite + 3,
                        length,
                        left_offset,
                        right_offset,
                    )

            return np.nan

        if now_psite > right_offset:
            return self.shift_codon(now_psite - 3, length, left_offset, right_offset)

        if now_psite < left_offset:
            return self.shift_codon(now_psite + 3, length, left_offset, right_offset)

        return np.nan

    def _select_sscbm_profile(self) -> pd.DataFrame:
        """Select SSCBM profile according to align mode."""
        tis_5end = self.tis_5end.T.copy()
        tis_5end.index = abs(tis_5end.index)

        tts_5end = self.tts_5end.T.copy()
        tts_5end.index = abs(tts_5end.index)

        if self.align == "tis":
            return tis_5end

        if self.align == "tts":
            return tts_5end

        if self.align == "both":
            return tis_5end + tts_5end

        print("Please input the correct align mode: tis, tts, both.", flush=True)
        print("Use the default mode: both.", flush=True)
        return tis_5end + tts_5end

    @staticmethod
    def _safe_fraction(numerator: float, denominator: float) -> float:
        """Return safe fraction, avoiding division by zero."""
        if denominator == 0:
            return 0.0

        return float(numerator) / float(denominator)

    def adjust_tis_offset(self) -> None:
        """Infer SSCBM P-site offset from read-end profiles.

        Workflow
        --------
        1. Merge the selected TIS/TTS 5'-end profile.
        2. Define candidate offset range for each read length.
        3. Select the peak candidate offset.
        4. Calculate frame counts around the selected candidate.
        5. Shift P-site into a reasonable range when needed.
        """
        offset_rpfs = self._select_sscbm_profile()

        for read_length in range(self.min_length, self.max_length + 1):
            shift_nt = (read_length - self.peak_length) // self.shift_nt
            left_offset = int(np.floor(self.peak_length / 3)) + shift_nt
            right_offset = int(np.ceil(self.peak_length * 3 / 4)) + shift_nt + 2
            candidate_offset = list(range(left_offset, right_offset))

            max_offset_site = offset_rpfs[read_length].idxmax()
            temp_offset_rpfs = offset_rpfs[read_length].copy()

            if temp_offset_rpfs[max_offset_site] == 0:
                max_offset_site = candidate_offset[min(5, len(candidate_offset) - 1)]

            while max_offset_site not in candidate_offset:
                temp_offset_rpfs = temp_offset_rpfs.drop(index=max_offset_site)
                max_offset_site = temp_offset_rpfs.idxmax()

            offset_frame0_range = range(max_offset_site - 3, max_offset_site + 6, 3)
            offset_frame1_range = range(max_offset_site - 2, max_offset_site + 6, 3)
            offset_frame2_range = range(max_offset_site - 1, max_offset_site + 6, 3)

            frame0_offset_rpfs = offset_rpfs[read_length][offset_frame0_range].sum()
            frame1_offset_rpfs = offset_rpfs[read_length][offset_frame1_range].sum()
            frame2_offset_rpfs = offset_rpfs[read_length][offset_frame2_range].sum()

            max_frame_offset_rpfs = max(
                frame0_offset_rpfs,
                frame1_offset_rpfs,
                frame2_offset_rpfs,
            )
            offset_sum = frame0_offset_rpfs + frame1_offset_rpfs + frame2_offset_rpfs
            periodicity = self._safe_fraction(max_frame_offset_rpfs, offset_sum)

            psite = max_offset_site + 1
            psite = self.shift_codon(psite, read_length, left_offset, right_offset + 1)

            self.adj_tis_offset[read_length] = [
                read_length,
                max_offset_site,
                frame0_offset_rpfs,
                max_offset_site + 1,
                frame1_offset_rpfs,
                max_offset_site + 2,
                frame2_offset_rpfs,
                psite,
                offset_sum,
                periodicity,
            ]

    def write_tis_offset(self) -> None:
        """Write SSCBM offset table."""
        adj_tis_offset = pd.DataFrame(self.adj_tis_offset).T.copy()
        adj_tis_offset.columns = TIS_OFFSET_COLUMNS
        adj_tis_offset["periodicity"] = adj_tis_offset["periodicity"] * 100
        adj_tis_offset["periodicity"] = (
            adj_tis_offset["periodicity"].astype(float).round(2)
        )

        integer_columns = [
            "length",
            "frame0",
            "rpfs0",
            "frame1",
            "rpfs1",
            "frame2",
            "rpfs2",
            "p_site",
            "rpfs",
        ]
        adj_tis_offset[integer_columns] = adj_tis_offset[integer_columns].fillna(0)
        adj_tis_offset[integer_columns] = adj_tis_offset[integer_columns].astype(int)
        adj_tis_offset.sort_values(["length"], inplace=True)
        adj_tis_offset["ribo"] = ["first"] * self.nt_num

        adj_tis_offset.to_csv(
            self.output_prefix + "_SSCBM_offset.txt",
            sep="\t",
            index=False,
        )

    def draw_tis_heatmap(self) -> None:
        """Draw raw and scaled SSCBM heatmaps."""
        import matplotlib

        matplotlib.use("Agg")

        import matplotlib.pyplot as plt
        import seaborn as sns

        def draw_figure(
            tis_5end: pd.DataFrame,
            tis_3end: pd.DataFrame,
            tts_5end: pd.DataFrame,
            tts_3end: pd.DataFrame,
            out_pdf: str,
            out_png: str,
        ) -> None:
            now_cmap = "Blues"
            fig = plt.figure(figsize=(12, 8), dpi=300)

            ax1 = plt.subplot(2, 2, 1)
            sns.heatmap(data=tis_5end, annot=None, linewidths=0.5, ax=ax1, cmap=now_cmap)
            ax1.set_title("RPFs 5end")
            ax1.set_ylabel("RPFs length")
            ax1.set_xlabel("from start codon")

            ax2 = plt.subplot(2, 2, 2)
            sns.heatmap(data=tis_3end, annot=None, linewidths=0.5, ax=ax2, cmap=now_cmap)
            ax2.set_title("RPFs 3end")
            ax2.set_ylabel("RPFs length")
            ax2.set_xlabel("from start codon")

            ax3 = plt.subplot(2, 2, 3)
            sns.heatmap(data=tts_5end, annot=None, linewidths=0.5, ax=ax3, cmap=now_cmap)
            ax3.set_title("RPFs 5end")
            ax3.set_ylabel("RPFs length")
            ax3.set_xlabel("from stop codon")

            ax4 = plt.subplot(2, 2, 4)
            sns.heatmap(data=tts_3end, annot=None, linewidths=0.5, ax=ax4, cmap=now_cmap)
            ax4.set_title("RPFs 3end")
            ax4.set_ylabel("RPFs length")
            ax4.set_xlabel("from stop codon")

            plt.tight_layout()
            fig.savefig(fname=out_pdf)
            fig.savefig(fname=out_png)
            plt.close(fig)

        draw_figure(
            self.tis_5end,
            self.tis_3end,
            self.tts_5end,
            self.tts_3end,
            self.output_prefix + "_SSCBM_offset.pdf",
            self.output_prefix + "_SSCBM_offset.png",
        )

        draw_figure(
            self.offset_scale(self.tis_5end),
            self.offset_scale(self.tis_3end),
            self.offset_scale(self.tts_5end),
            self.offset_scale(self.tts_3end),
            self.output_prefix + "_SSCBM_offset_scale.pdf",
            self.output_prefix + "_SSCBM_offset_scale.png",
        )

    # ------------------------------------------------------------------
    # RSBM offset detection
    # ------------------------------------------------------------------

    def make_frame_offset(self) -> None:
        """Make RSBM candidate offsets.

        If SSCBM offsets are available, they are used as seeds. Otherwise, the
        empirical fallback offset is used.
        """
        self.exp_offset = 11 + self.peak_length - 30

        if self.adj_tis_offset:
            for read_length in range(self.min_length, self.max_length + 1):
                self.exp_offset = self.adj_tis_offset[read_length][1]
                self.frame_offset_len[read_length] = [
                    self.exp_offset,
                    self.exp_offset + 1,
                    self.exp_offset + 2,
                ]
                self.frame_offset[read_length] = [0, 0, 0]
            return

        for read_length in range(self.min_length, self.max_length + 1):
            shift_nt = (read_length - self.peak_length) // self.shift_nt
            shift_nt = max(-3, min(6, shift_nt))

            left_offset1 = self.exp_offset + shift_nt
            left_offset2 = self.exp_offset + 1 + shift_nt
            left_offset3 = self.exp_offset + 2 + shift_nt

            self.frame_offset_len[read_length] = [
                left_offset1,
                left_offset2,
                left_offset3,
            ]
            self.frame_offset[read_length] = [0, 0, 0]

    def calc_frame(
        self,
        map_start: int,
        cds_start: int,
        read_length: int,
        num1: int,
        num2: int,
        num3: int,
    ) -> None:
        """Count the candidate offset frame for one read."""
        if (
            map_start + self.frame_offset_len[read_length][num1] - cds_start
        ) % 3 == 0:
            self.frame_offset[read_length][num1] += 1
        elif (
            map_start + self.frame_offset_len[read_length][num2] - cds_start
        ) % 3 == 0:
            self.frame_offset[read_length][num2] += 1
        elif (
            map_start + self.frame_offset_len[read_length][num3] - cds_start
        ) % 3 == 0:
            self.frame_offset[read_length][num3] += 1

    def get_mono_frame(self, mrna_attr: Mrna, cds_start: int) -> None:
        """Collect RSBM frame counts for monosome data."""
        for read in mrna_attr.bam:
            blocks = read.get_blocks()

            if not blocks:
                continue

            map_start, _map_end = blocks[0]
            read_length = read.infer_read_length()

            if read_length is None:
                continue

            if self.min_length <= read_length <= self.max_length:
                self.calc_frame(map_start, cds_start, read_length, 0, 1, 2)

    def get_frame_offset(self) -> None:
        """Calculate RSBM offset from transcript-mapped reads."""
        self.make_frame_offset()

        for mrna_attr in self.mrna_dict.values():
            if len(mrna_attr.bam) == 0:
                continue

            cds_start = mrna_attr.utr5_length
            self.get_mono_frame(mrna_attr, cds_start)

    def format_frame_offset(self) -> None:
        """Format raw RSBM frame counts into the final offset table."""
        ribo = [["first"], ["second"], ["third"]]
        frame_offset = pd.DataFrame(self.frame_offset).T
        rows, cols = frame_offset.shape

        def get_offset_len(temp_offset: pd.DataFrame) -> None:
            for read_length, frame_index in dict(temp_offset.idxmax(1)).items():
                if frame_index in [0, 1]:
                    temp_offset.loc[read_length, "p_site"] = (
                        self.frame_offset_len[read_length][frame_index] + 1
                    )
                elif frame_index == 2:
                    temp_offset.loc[read_length, "p_site"] = (
                        self.frame_offset_len[read_length][frame_index] + 1 - 3
                    )

        for part in range(0, cols, 3):
            temp_offset = frame_offset.iloc[:, part : part + 3].copy()
            get_offset_len(temp_offset)

            temp_offset["sum"] = temp_offset.iloc[:, 0:3].sum(axis=1)
            temp_offset.columns = ["rpfs0", "rpfs1", "rpfs2", "p_site", "rpfs"]
            temp_offset[["frame0", "frame1", "frame2"]] = [
                offsets[part : part + 3] for offsets in self.frame_offset_len.values()
            ]
            temp_offset["length"] = temp_offset.index

            self.merge_frame_offset = pd.concat(
                [self.merge_frame_offset, temp_offset[FRAME_COLUMNS]],
                ignore_index=True,
            )

            self.merge_frame_offset["periodicity"] = np.divide(
                self.merge_frame_offset[["rpfs0", "rpfs1", "rpfs2"]].max(axis=1),
                self.merge_frame_offset["rpfs"],
                out=np.zeros(len(self.merge_frame_offset), dtype=float),
                where=self.merge_frame_offset["rpfs"].to_numpy() != 0,
            )
            self.merge_frame_offset["periodicity"] = (
                self.merge_frame_offset["periodicity"] * 100
            )
            self.merge_frame_offset["periodicity"] = (
                self.merge_frame_offset["periodicity"].astype(float).round(2)
            )
            self.merge_frame_offset["ribo"] = ribo[part // 3] * rows
            self.merge_frame_offset[FRAME_COLUMNS] = self.merge_frame_offset[
                FRAME_COLUMNS
            ].astype(int)

    def _get_psite_by_length(self, read_length: int) -> int | None:
        """Return P-site offset for one read length, if available."""
        rows = self.merge_frame_offset.loc[
            self.merge_frame_offset["length"] == read_length,
            "p_site",
        ].reset_index(drop=True)

        if rows.empty:
            return None

        return int(rows.iloc[0])

    def adjust_frame_offset(self) -> None:
        """Normalize offsets across adjacent read lengths."""
        for read_length in range(self.peak_length, self.min_length, -1):
            psite1 = self._get_psite_by_length(read_length)
            psite2 = self._get_psite_by_length(read_length - 1)

            if psite1 is None or psite2 is None:
                continue

            if psite2 + 2 < psite1:
                self.merge_frame_offset.loc[
                    self.merge_frame_offset["length"] == read_length - 1,
                    "p_site",
                ] = psite2 + 3
            elif psite2 - 2 > psite1:
                self.merge_frame_offset.loc[
                    self.merge_frame_offset["length"] == read_length - 1,
                    "p_site",
                ] = psite2 - 3

        for read_length in range(self.peak_length, self.max_length, 1):
            psite1 = self._get_psite_by_length(read_length)
            psite2 = self._get_psite_by_length(read_length + 1)

            if psite1 is None or psite2 is None:
                continue

            if psite2 - 2 > psite1:
                self.merge_frame_offset.loc[
                    self.merge_frame_offset["length"] == read_length + 1,
                    "p_site",
                ] = psite2 - 3
            elif psite2 + 2 < psite1:
                self.merge_frame_offset.loc[
                    self.merge_frame_offset["length"] == read_length + 1,
                    "p_site",
                ] = psite2 + 3

    def write_frame_offset(self) -> None:
        """Arrange frame counts relative to predicted P-site and write table."""
        for row_index in range(self.merge_frame_offset.shape[0]):
            offset_line = self.merge_frame_offset.iloc[row_index, :]

            offset_psite = offset_line[["frame0", "frame1", "frame2"]].copy()
            offset_rpfs = offset_line[["rpfs0", "rpfs1", "rpfs2"]].copy()

            offset_index = (offset_psite.astype(int) - int(offset_line["p_site"]) + 1) % 3

            offset_psite.index = offset_index
            offset_rpfs.index = offset_index

            offset_psite = offset_psite.loc[[0, 1, 2]]
            offset_rpfs = offset_rpfs.loc[[0, 1, 2]]

            self.merge_frame_offset.loc[
                self.merge_frame_offset.index[row_index],
                ["frame0", "frame1", "frame2"],
            ] = offset_psite.to_list()
            self.merge_frame_offset.loc[
                self.merge_frame_offset.index[row_index],
                ["rpfs0", "rpfs1", "rpfs2"],
            ] = offset_rpfs.to_list()

        self.merge_frame_offset.to_csv(
            self.output_prefix + "_RSBM_offset.txt",
            sep="\t",
            index=False,
        )

    def draw_frame_heatmap(self) -> None:
        """Draw raw and scaled RSBM frame heatmaps."""
        import matplotlib

        matplotlib.use("Agg")

        import matplotlib.pyplot as plt
        import seaborn as sns

        out_pdf = self.output_prefix + "_RSBM_offset.pdf"
        out_png = self.output_prefix + "_RSBM_offset.png"

        raw_frame_offset = self.merge_frame_offset.loc[
            :,
            ["length", "p_site", "rpfs0", "rpfs1", "rpfs2"],
        ].copy()

        offset_num = raw_frame_offset.shape[0]
        raw_frame_offset.index = [
            str(raw_frame_offset["length"].to_list()[idx])
            + "_"
            + str(raw_frame_offset["p_site"].to_list()[idx])
            for idx in range(offset_num)
        ]

        raw_frame_offset = raw_frame_offset.drop(columns=["length", "p_site"])
        raw_frame_offset.columns = ["frame0", "frame1", "frame2"]
        raw_frame_offset = raw_frame_offset.apply(pd.to_numeric)

        scale_frame_offset = self.offset_scale(raw_frame_offset)
        scale_frame_offset = scale_frame_offset.apply(pd.to_numeric)

        now_cmap = "Blues"
        fig = plt.figure(figsize=(12, 6), dpi=300)

        ax1 = plt.subplot(1, 2, 1)
        sns.heatmap(
            data=raw_frame_offset,
            annot=None,
            linewidths=0.5,
            ax=ax1,
            cmap=now_cmap,
        )
        ax1.set_title("raw counts")
        ax1.set_ylabel("RPFs length")
        ax1.set_xlabel("open reading frame")

        ax2 = plt.subplot(1, 2, 2)
        sns.heatmap(
            data=scale_frame_offset,
            annot=None,
            linewidths=0.5,
            ax=ax2,
            cmap=now_cmap,
        )
        ax2.set_title("scaled counts")
        ax2.set_ylabel("RPFs length")
        ax2.set_xlabel("open reading frame")

        plt.tight_layout()
        fig.savefig(fname=out_pdf)
        fig.savefig(fname=out_png)
        plt.close(fig)
